    '''@dataclass(frozen=True)
class Shape:
    window: int
    min_points: int
    seasonality: bool
    yearly: bool = False

    def as_dict(self) -> dict[str, Any]:
        return {
            "window": self.window,
            "min_points": self.min_points,
            "seasonality": self.seasonality,
            "yearly": self.yearly,
        }

    def for_metric(self, target_metric: Any) -> dict[str, Any]:
        """The shape keys a baseline on ``target_metric`` runs on: ``yearly`` only where the
        metric takes it."""
        return {k: v for k, v in self.as_dict().items() if k in shape_keys(target_metric)}


