    return row


def test_read_reports_the_defaults_when_nothing_is_stored(client: TestClient) -> None:
    body = client.get("/api/v1/admin/coverage").json()

    defaults = {
        "sensitivity": dict.fromkeys(svc.BASELINES, _DEFAULT),
        "baseline": {
            "window": 8,
            "min_points": 4,
